def vacmet_inputs_from_equilibrium_data(
    equilibrium_data,
    *,
    wall=None,
    wall_scale: float = 1.0,
    nowall: int = 1,
    radial_index: int = -1,
):
    radial_grid = equilibrium_data.radial_grid
    data = dict(equilibrium_data.data)
    geometry = {
        "R": data.get("R"),
        "Z": data.get("Z"),
        "phi": data.get("phi", data.get("V")),
        "Rs": data.get("Rs", data.get("R_s", data.get("R_r"))),
        "Rt": data.get("Rt", data.get("R_theta", data.get("R_t"))),
        "Rp": data.get("Rp", data.get("R_zeta", data.get("R_z"))),
        "Zs": data.get("Zs", data.get("Z_s", data.get("Z_r"))),
        "Zt": data.get("Zt", data.get("Z_theta", data.get("Z_t"))),
        "Zp": data.get("Zp", data.get("Z_zeta", data.get("Z_z"))),
        "phis": data.get("phis", data.get("phi_s", data.get("phi_r", data.get("V_s")))),
        "phit": data.get("phit", data.get("phi_theta", data.get("phi_t", data.get("V_t")))),
        "phip": data.get("phip", data.get("phi_zeta", data.get("phi_z", data.get("V_z")))),
        "Rst": data.get("Rst", data.get("R_st", data.get("R_s_theta"))),
        "Rsp": data.get("Rsp", data.get("R_sp", data.get("R_s_zeta"))),
        "Zst": data.get("Zst", data.get("Z_st", data.get("Z_s_theta"))),
        "Zsp": data.get("Zsp", data.get("Z_sp", data.get("Z_s_zeta"))),
        "phist": data.get("phist", data.get("phi_st", data.get("phi_s_theta", data.get("V_st")))),
        "phisp": data.get("phisp", data.get("phi_sp", data.get("phi_s_zeta", data.get("V_sp")))),
